requireRole(['Administrator']);require_once __DIR__.'/../app/layout.php';$pdo=db(); ensureUserAccessSchema($pdo);$me=currentUser();$myId=(int)($me['id']??0);
$divisions=$pdo->query('SELECT id,name,division_head,head_position_designation FROM divisions ORDER BY name')->fetchAll();
