if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=$_POST['action']??'';if($action==='update_my_account'){if(!hasRole(['Administrator'])||$myId<=0){http_response_code(403);exit('403 - Access denied');}$username=trim((string)($_POST['username']??''));$agencyId=trim((string)($_POST['agency_id']??''));$email=trim((string)($_POST['email']??''));$newPassword=(string)($_POST['new_password']??'');if($username===''){flash('error','User ID is required.');}elseif($newPassword!==''&&strlen($newPassword)<8){flash('error','New password must be at least 8 characters.');}else{try{$check=$pdo->prepare("SELECT id FROM users WHERE (username=? OR (?<>'' AND agency_id=?)) AND id<>? LIMIT 1");$check->execute([$username,$agencyId,$agencyId,$myId]);if($check->fetch()){flash('error','That User ID or Agency ID is already assigned to another account.');}else{if($newPassword!==''){$st=$pdo->prepare('UPDATE users SET username=?,agency_id=?,email=?,password_hash=?,must_change_password=0 WHERE id=?');$st->execute([$username,$agencyId===''?null:$agencyId,$email,password_hash($newPassword,PASSWORD_DEFAULT),$myId]);}else{$st=$pdo->prepare('UPDATE users SET username=?,agency_id=?,email=? WHERE id=?');$st->execute([$username,$agencyId===''?null:$agencyId,$email,$myId]);}$refresh=$pdo->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$refresh->execute([$myId]);$fresh=$refresh->fetch();if($fresh){$_SESSION['user']=$fresh;}flash('success','Your account has been updated.');}}catch(Throwable $e){flash('error','Unable to update your account. Please check the User ID and Agency ID.');}}header('Location:users.php');exit;}elseif($action==='update_user'){if(!hasRole(['Administrator'])){http_response_code(403);exit('403 - Access denied');}$id=(int)($_POST['id']??0);if($id<=0||$id===$myId){flash('error','Use Edit My Account to change your own account.');header('Location:users.php');exit;}$username=trim((string)($_POST['username']??''));$agencyId=trim((string)($_POST['agency_id']??''));$fullName=trim((string)($_POST['full_name']??''));$email=trim((string)($_POST['email']??''));$role=(string)($_POST['role']??'Viewer');$status=(string)($_POST['status']??'Active');$divisionId=(int)($_POST['division_id']??0);$areaId=(int)($_POST['area_id']??0);$newPassword=(string)($_POST['new_password']??'');if($username===''||$fullName===''){flash('error','User ID and Name / Full Name are required.');}elseif(!in_array($role,['Administrator','Editor','Viewer','Guest'],true)||!in_array($status,['Active','Inactive'],true)){flash('error','Invalid role or status.');}elseif($newPassword!==''&&strlen($newPassword)<8){flash('error','New password must be at least 8 characters.');}else{try{$check=$pdo->prepare("SELECT id FROM users WHERE (username=? OR (?<>'' AND agency_id=?)) AND id<>? LIMIT 1");$check->execute([$username,$agencyId,$agencyId,$id]);if($check->fetch()){flash('error','That User ID or Agency ID is already assigned to another account.');}else{if($areaId>0){$areaCheck=$pdo->prepare('SELECT id FROM areas WHERE id=? AND division_id=? LIMIT 1');$areaCheck->execute([$areaId,$divisionId]);if(!$areaCheck->fetchColumn()){$areaId=0;}}if($newPassword!==''){$st=$pdo->prepare('UPDATE users SET username=?,agency_id=?,full_name=?,email=?,role=?,status=?,division_id=?,area_id=?,password_hash=?,must_change_password=0 WHERE id=?');$st->execute([$username,$agencyId===''?null:$agencyId,$fullName,$email,$role,$status,$divisionId>0?$divisionId:null,$areaId>0?$areaId:null,password_hash($newPassword,PASSWORD_DEFAULT),$id]);}else{$st=$pdo->prepare('UPDATE users SET username=?,agency_id=?,full_name=?,email=?,role=?,status=?,division_id=?,area_id=? WHERE id=?');$st->execute([$username,$agencyId===''?null:$agencyId,$fullName,$email,$role,$status,$divisionId>0?$divisionId:null,$areaId>0?$areaId:null,$id]);}flash('success','User account updated.');}}catch(Throwable $e){flash('error','Unable to update user account. Please check the User ID and Agency ID.');}}header('Location:users.php');exit;}elseif($action==='delete_user'){if(!hasRole(['Administrator'])){http_response_code(403);exit('403 - Access denied');}$id=(int)($_POST['id']??0);if($id<=0||$id===$myId){flash('error','You cannot delete your own account.');}else{$st=$pdo->prepare('DELETE FROM users WHERE id=?');$st->execute([$id]);$deleted=$st->rowCount();flash($deleted?'success':'error',$deleted?'User account deleted.':'User account was not found.');}header('Location:users.php');exit;}elseif($action==='create'){$p=$_POST['password']??'';if(strlen($p)<8){flash('error','Password must be at least 8 characters.');}else{$divisionId=(int)($_POST['division_id']??0);
$personName=trim($_POST['full_name']??'');
$person=$pdo->prepare('SELECT ap.name,ap.area_id FROM area_personnel ap JOIN areas a ON a.id=ap.area_id WHERE a.division_id=? AND ap.name=? LIMIT 1');
$person->execute([$divisionId,$personName]);$personRow=$person->fetch();
$head=$pdo->prepare('SELECT division_head FROM divisions WHERE id=? AND division_head=? LIMIT 1');
$head->execute([$divisionId,$personName]);$isDivisionHead=(bool)$head->fetchColumn();
$canonicalName=$personRow['name']??($isDivisionHead?$personName:'');
$areaId=(int)($personRow['area_id']??0);
if($divisionId<=0 || $canonicalName===''){flash('error','Please select a valid Division/Department and Name / Full Name assigned to that Division.');}
else{
$st=$pdo->prepare('INSERT INTO users(username,agency_id,full_name,email,password_hash,role,status,must_change_password,division_id,area_id) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([trim($_POST['username']),(($a=trim($_POST['agency_id']??''))===''?null:$a),$canonicalName,trim($_POST['email']),password_hash($p,PASSWORD_DEFAULT),$_POST['role'],$_POST['status'],1,$divisionId,$areaId]);flash('success','User created.');}}}elseif($action==='toggle'){$pdo->prepare('UPDATE users SET status=IF(status="Active","Inactive","Active") WHERE id=?')->execute([(int)$_POST['id']]);flash('success','User status updated.');}header('Location:users.php');exit;}$editId=(int)($_GET['edit']??0);$editUser=null;if($editId>0&&$editId!==$myId){$st=$pdo->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$st->execute([$editId]);$editUser=$st->fetch()?:null;}$rows=$pdo->query('SELECT u.id,u.username,u.agency_id,u.full_name,u.email,u.role,u.status,u.created_at,u.division_id,u.area_id,d.name division_name,a.name area_name FROM users u LEFT JOIN divisions d ON d.id=u.division_id LEFT JOIN areas a ON a.id=u.area_id ORDER BY u.full_name')->fetchAll();pageStart('User Management');
?><div class="grid"><div class="panel user-list-panel"><h2>Users</h2><div class="user-table-wrap"><table class="table user-management-table"><thead><tr><th>Name</th><th>User ID / Agency ID</th><th>Division / Area</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['username'])?><br><small><?=e($r['agency_id']??'')?></small></td><td><?=e($r['division_name']??'Not assigned')?> / <?=e($r['area_name']??'Not assigned')?></td><td><?=e($r['role'])?></td><td><div class="user-status-actions"><form method="post" class="user-status-toggle-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="user-status-toggle <?=($r['status']==='Active'?'is-active':'is-inactive')?>" type="submit"<?=($r['id']===currentUser()['id']?' disabled title="You cannot deactivate your own account"':'')?>><span class="user-status-toggle-label"><?=e($r['status']==='Active'?'Active':'Inactive')?></span><span class="user-status-toggle-knob"></span></button></form><?php if((int)$r["id"]!==$myId):?><div class="user-row-actions"><a class="btn secondary master-action" href="users.php?edit=<?=(int)$r["id"]?>">Edit</a><form method="post" class="master-action-form" onsubmit="return confirm('Delete this user account? This cannot be undone.')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_user"><input type="hidden" name="id" value="<?=(int)$r["id"]?>"><button class="btn danger master-action" type="submit">Delete</button></form></div><?php else:?><div class="user-row-actions"><a class="btn secondary master-action" href="#edit-my-account">Edit</a></div><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div><?php if($editUser):?><div class="panel"><h2>Edit User Account</h2><form method="post"><input typ