"")?>>Inactive</option></select></div><div class="field"><label>New Password (leave blank to keep current password)</label><input class="input" type="password" name="new_password" minlength="8" autocomplete="new-password"></div><div class="actions"><button class="btn">Save Changes</button><a class="btn btn-secondary" href="users.php">Cancel</a></div></form></div><script>(function(){const d=document.getElementById("editUserDivision"),a=document.getElementById("editUserArea");function filterAreas(){Array.from(a.options).forEach((o,i)=>{if(i)o.hidden=!!d.value&&o.dataset.division!==d.value;});if(a.selectedOptions[0]&&a.selectedOptions[0].hidden)a.value="0";}d.addEventListener("change",filterAreas);filterAreas();})();</script><?php endif;?><div class="panel" id="edit-my-account"><h2>Edit My Account</h2><p class="muted">You can edit only your own account details. Your role, status, and Division/Area assignment cannot be changed here.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update_my_account"><div class="field"><label>User ID</label><input class="input" name="username" value="<?=e((string)($me['username']??''))?>" required></div><div class="field"><label>Agency ID (optional)</label><input class="input" name="agency_id" value="<?=e((string)($me['agency_id']??''))?>"></div><div class="field"><label>Email</label><input class="input" type="email" name="email" value="<?=e((string)($me['email']??''))?>"></div><div class="field"><label>New Password (leave blank to keep current password)</label><input class="input" type="password" name="new_password" minlength="8" autocomplete="new-password"></div><div class="actions"><button class="btn">Save My Account</button></div></form></div><div class="panel"><h2>Create User</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create">
